// ============================================================================
// WF-27 · צומת 1 — קליטת טופס "תשלום שאינו באשראי" ונירמול
// ============================================================================
// הטופס יושב ככפתור בכרטיס תהליך המכירה בפיירברי, ושולח לכאן את כל מה
// שהנציגה הזינה. מכאן והלאה הזרימה זהה בהתנהגותה ל-WF-20:
// רשומת תשלום (1039) לכל אמצעי תשלום, תיעודי תשלום (1018) לפי לוח החיובים,
// ובסיום — הפעלת התהליך המקצועי, אך ורק אם סומן "רכישה של מוצר חדש".
// ============================================================================

// ==== LOGIC (pure) ====
const CFG = {
  DRY_RUN: false,
  VAT_PERCENT: 18,
  FIREBERRY_BASE: 'https://api.fireberry.com',
  N8N_BASE: 'https://n8n.srv964196.hstgr.cloud',
  PRO_WEBHOOK_URL: 'https://n8n.srv964196.hstgr.cloud/webhook/pro-setup-roital',
  INSTALLMENT_INTERVAL_MONTHS: 1,
  DEFAULT_TASK_PRIORITY: 5, DEFAULT_TASK_TYPE: 5, DEFAULT_TASK_STATUS: 1,
  // 1018.pcfPaymetStatus — שים לב לאיות: Paymet בלי n. כך זה בפיירברי.
  DOC_PAID: 1, DOC_PENDING: 3,
  PAY_STATUS_IN_PROGRESS: 1, PAY_STATUS_SETTLED: 2,
};

function LOGIC(ctx) {
  const cfg = Object.assign({}, CFG, ctx.cfgOverride || {});
  const raw = ctx.raw || {};
  const d = (raw && raw.body && typeof raw.body === 'object') ? raw.body : raw;

  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const N = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
  const normPhone = (p) => {
    let x = S(p).replace(/\D/g, '');
    if (x.indexOf('972') === 0) x = '0' + x.slice(3);
    return x;
  };

  const nowISO = ctx.nowISO || new Date().toISOString();
  const todayISO = nowISO.slice(0, 10) + 'T00:00:00Z';
  const toISO = (s) => {
    const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m ? `${m[1]}-${m[2]}-${m[3]}T00:00:00Z` : null;
  };

  const rowsIn = Array.isArray(d.payments) ? d.payments : [];
  const payments = rowsIn.map((p, i) => {
    const gross = N(p.amount_including_vat);
    const count = Math.max(1, parseInt(p.number_of_payments, 10) || 1);
    return {
      index: i + 1,
      fbPaymentType: parseInt(p.payment_type, 10) || 1,
      typeLabel: S(p.payment_type_label) || 'תשלום',
      isAmex: !!p.is_amex,
      gross, count,
      perGross: N(p.amount_per_payment) || Math.round((gross / count) * 100) / 100,
      firstDateISO: toISO(p.first_payment_date) || todayISO,
      notes: S(p.notes),
    };
  }).filter((p) => p.gross > 0);

  // 🔴 מפתח אידמפוטנטיות — הטופס מייצר מזהה שליחה אחד לכל טעינת עמוד.
  //    לחיצה כפולה על "שליחה" לא תיצור רשומות כפולות.
  const submissionId = S(d.submission_id) || S(d.opportunity_id) + '-' + todayISO.slice(0, 10);
  const idemBase = `MANUAL-${submissionId}`;

  return [{
    json: {
      _cfg: cfg,
      _raw: d,
      source: 'manual_payment_button',
      submissionId, idemBase,
      accountid: S(d.account_id),
      accountName: S(d.account_name) || 'לקוחה',
      phone: normPhone(d.phone || d.telephone1),
      saleid: S(d.opportunity_id),
      ownerid: S(d.owner_id),
      productId: S(d.purchased_product_id) || S(d.product_id),
      productName: S(d.purchased_product_name) || S(d.product_name) || 'מוצר לא מזוהה',
      newProductPurchase: d.new_product_purchase === true || S(d.new_product_purchase) === 'true',
      whatsappGroupId: S(d.whatsapp_group_id),
      whatsappGroupName: S(d.whatsapp_group_name),
      dealAmount: N(d.deal_amount),
      totalEntered: N(d.total_entered),
      payments,
      paymentsCount: payments.length,
      nowISO, todayISO,
      executionUrl: S(d.executionUrl),
      DRY_RUN: cfg.DRY_RUN === true,
    },
  }];
}

// ==== N8N BINDING ====
return LOGIC({ raw: $input.first().json, executionUrl: $execution.resumeUrl });

// ============================================================================
// WF-27 · בניית תוכנית הפעולה — תשלום שאינו באשראי
// ============================================================================
// אותה חוקיות בדיוק כמו בענף "רכישה חדשה" של WF-20:
//   רשומת תשלום (1039) לכל אמצעי תשלום · תיעוד תשלום (1018) לכל חיוב בלוח
//   הזמנים · הערה על תהליך המכירה, על התשלום ועל התיעודים.
// ההבדל היחיד: הנתונים מגיעים מטופס ולא מוובהוק של גרואו.
// ============================================================================

// ==== LOGIC (pure) ====
function PLAN_CORE(ctx) {
  const ev = ctx.ev;
  const cfg = ev._cfg;
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const U = (v) => S(v).toUpperCase();
  const rows = (r) => {
    if (!r) return [];
    if (Array.isArray(r)) return r;
    if (Array.isArray(r.data)) return r.data;
    if (r.data && Array.isArray(r.data.Data)) return r.data.Data;
    if (r.data && r.data.Record) return [r.data.Record];
    return [];
  };
  const cut = (s, n) => { const t = S(s); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  // 🔴 פיירברי מחשב את הסכום כולל מע"מ מתוך הסכום שלפניו ומעגל ל-4 ספרות.
  //    עיגול ל-2 היה מייצר סטייה גלויה. (נתפס חי ב-WF-20, 19/08.)
  const round4 = (n) => Math.round((Number(n) || 0) * 10000) / 10000;
  const money = (n) => (Math.round((Number(n) || 0) * 100) / 100).toLocaleString('he-IL') + ' ₪';

  function addMonthsISO(iso, months) {
    const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!m) return null;
    let y = parseInt(m[1], 10);
    let mo = parseInt(m[2], 10) - 1 + months;
    let dd = parseInt(m[3], 10);
    y += Math.floor(mo / 12); mo = ((mo % 12) + 12) % 12;
    const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    const dim = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo];
    if (dd > dim) dd = dim;
    const p = (x) => String(x).padStart(2, '0');
    return `${y}-${p(mo + 1)}-${p(dd)}T00:00:00Z`;
  }

  const ops = [];
  const warnings = [];
  const decisions = [];
  const add = (o) => { ops.push(o); return '@' + o.ref; };
  const lookupOrOmit = (obj, key, val) => { if (S(val)) obj[key] = S(val); return obj; };

  const sales = rows(ctx.saleResp);
  const existingPays = rows(ctx.existingPayResp);
  const products = rows(ctx.productResp);
  const mentorings = rows(ctx.mentoringResp);
  const allSales = rows(ctx.openSalesResp);

  const custLabel = ev.accountName || 'לקוחה';
  const sale = sales.find((s) => U(s.opportunityid) === U(ev.saleid)) || sales[0] || null;
  const saleId = sale ? S(sale.opportunityid) : S(ev.saleid);
  const ownerid = S(ev.ownerid) || S(sale && sale.ownerid);
  const product = products.find((p) => U(p.productid) === U(ev.productId)) || null;
  const productName = product ? S(product.name) : ev.productName;

  // ---------- אידמפוטנטיות ----------
  const dup = existingPays.find((p) => S(p.pcfExternalSoftwareID1).indexOf(ev.idemBase) === 0);
  if (dup) {
    decisions.push('DUPLICATE — הטופס הזה כבר נשלח ונקלט.');
    return { branch: 'DUPLICATE', ops: [], warnings, decisions,
      summary: 'השליחה הזו כבר נקלטה — לא נוצרו רשומות נוספות.',
      saleId, productName, firePro: false };
  }

  if (!ev.payments.length) {
    warnings.push('לא התקבל אף אמצעי תשלום עם סכום.');
    return { branch: 'EMPTY', ops: [], warnings, decisions,
      summary: 'לא התקבלו נתוני תשלום — לא נוצרה שום רשומה.',
      saleId, productName, firePro: false };
  }
  if (!saleId) warnings.push('לא נמסר תהליך מכירה — הרשומות ייווצרו בלי שיוך.');
  if (!ev.accountid) warnings.push('לא נמסרה לקוחה — הרשומות ייווצרו בלי שיוך.');
  if (ev.dealAmount && Math.abs(ev.totalEntered - ev.dealAmount) > 0.01) {
    warnings.push(`הסכום שהוזן (${money(ev.totalEntered)}) שונה מסכום העסקה (${money(ev.dealAmount)}).`);
  }

  const vat = 1 + (cfg.VAT_PERCENT / 100);
  const execLink = ev.executionUrl ? `<a href="${ev.executionUrl}">${ev.executionUrl}</a>` : 'טופס ידני';

  // תאריך בפורמט ישראלי לתצוגה בשם הרשומה
  const ilDate = (iso) => {
    const d = String(iso || '').slice(0, 10).split('-');
    return d.length === 3 ? `${d[2]}/${d[1]}/${d[0]}` : String(iso || '');
  };

  // חיוב שתאריכו עבר או היום נחשב שנפרע. כשכל החיובים כאלה — התשלום סגור.
  const dueIsPast = (iso) => String(iso || '').slice(0, 10) <= String(ev.todayISO).slice(0, 10);
  const allDue = (pp) => {
    for (let i = 0; i < pp.count; i++) {
      if (!dueIsPast(addMonthsISO(pp.firstDateISO, i * (cfg.INSTALLMENT_INTERVAL_MONTHS || 1)))) return false;
    }
    return true;
  };

  ev.payments.forEach((p) => {
    const ref = 'pay' + p.index;
    const many = ev.payments.length > 1;
    const payName = `התשלום של ${custLabel} | ${productName} | ${money(p.gross)} | ` +
      `${p.count} תשלומים · ${p.typeLabel}`;
    const lastDate = p.count > 1
      ? addMonthsISO(p.firstDateISO, (p.count - 1) * (cfg.INSTALLMENT_INTERVAL_MONTHS || 1))
      : p.firstDateISO;

    const payBody = {
      name: cut(payName, 190),
      // 🔴 תשלום שאינו אשראי לעולם אינו נפתח כ"נפרע" — אין ראיה שהכסף התקבל.
      pcfStatus: cfg.PAY_STATUS_IN_PROGRESS,
      pcfstatusupdatedate: ev.nowISO,
      pcfPaymentType: p.fbPaymentType,
      pcfNumberOfPayments: p.count,
      pcfNeedToPay: round4(p.gross / vat),
      pcfNeedToPayIncludingVat: p.gross,
      pcftaxincludecode: 1,
      pcfFirstPaymentDate: p.firstDateISO,
      pcfLastPaymentDate: lastDate,
      pcfNextPaymentDate: p.count > 1 ? addMonthsISO(p.firstDateISO, cfg.INSTALLMENT_INTERVAL_MONTHS || 1) : null,
      pcfCreatedByPersonOrSystem: 2,
      pcfExternalSoftwareID1: `${ev.idemBase}-P${p.index}`,
      pcfExternalSoftwareID2: 'MANUAL',
    };
    if (p.notes) payBody.pcfInvoicesDetails = cut(p.notes, 1000);
    lookupOrOmit(payBody, 'pcfAccountid', ev.accountid);
    lookupOrOmit(payBody, 'pcfSale', saleId);
    lookupOrOmit(payBody, 'ownerid', ownerid);
    lookupOrOmit(payBody, 'pcfrelatedproduct', ev.productId);
    const payRef = add({ ref, kind: 'create', object: '1039',
      label: `יצירת תשלום ${many ? p.index + ' · ' : ''}(1039) · ${p.typeLabel}`, body: payBody });

    // ---- תיעודי תשלום — אחד לכל חיוב בלוח הזמנים ----
    for (let i = 0; i < p.count; i++) {
      const due = addMonthsISO(p.firstDateISO, i * (cfg.INSTALLMENT_INTERVAL_MONTHS || 1));
      // ============================================================================
      // 🔴 שונה 20/08/2026 לפי הנחיית אליאל.
      // בתשלום שאינו אשראי אין שום אישור אוטומטי שהכסף התקבל — אין סליקה,
      // אין אסמכתא, אין וובהוק. גם החיוב הראשון הוא הבטחה בלבד.
      // לכן **כל** התיעודים נפתחים כ"ממתין לפירעון", והפירעון מסומן ידנית.
      // ============================================================================
      const paid = false;
      // 🔴 אין ב-1018 שדה "תאריך חיוב מתוכנן", ו-pcfPaymentDate פירושו
      //    "התאריך שבו הכסף התקבל" — אסור לכתוב בו תאריך עתידי.
      //    לכן מועד החיוב המתוכנן נשמר בשם הרשומה, כדי שהנציגה תראה אותו.
      const dueLabel = ilDate(due);
      const seq = p.count > 1 ? ` | חיוב ${i + 1}/${p.count}` : '';
      const docBody = {
        name: cut(`תיעוד התשלום של ${custLabel} | ${productName}${seq} | לתאריך ${dueLabel}`, 190),
        pcfPaymetStatus: paid ? cfg.DOC_PAID : cfg.DOC_PENDING,
        pcfsStatusUpdateTime: ev.nowISO,
        pcfPaymentType: p.fbPaymentType,
        pcftaxincludecode: 1,
        pcfPayed: round4(p.perGross / vat),
        pcfPayedIncludingVAT: p.perGross,
        pcfCreatedByPersonOrSystem: 2,
        pcfExternalSoftwareID1: `${ev.idemBase}-P${p.index}-${i + 1}`,
        pcfExternalSoftwareID2: 'MANUAL',
        // 🔴 השמטת השדה גורמת לפיירברי למלא אותו בתאריך היצירה. חייבים null מפורש.
        pcfPaymentDate: paid ? due : null,
        pcfPaymentCollection: payRef,
      };
      lookupOrOmit(docBody, 'pcfAccountid', ev.accountid);
      lookupOrOmit(docBody, 'pcfSale', saleId);
      lookupOrOmit(docBody, 'ownerid', ownerid);
      add({ ref: `${ref}d${i + 1}`, kind: 'create', object: '1018',
        label: `יצירת תיעוד תשלום ${i + 1}/${p.count} (1018)`, body: docBody });
    }
  });

  // ---------- הערות ----------
  const lines = ev.payments.map((p) =>
    `${p.typeLabel}: <b>${money(p.gross)}</b>${p.count > 1 ? ` · ${p.count} תשלומים של ${money(p.perGross)}` : ''}` +
    `${p.notes ? ' · ' + p.notes : ''}`).join('<br>');
  const noteHtml = `<div dir="rtl">נקלט תשלום שאינו באשראי, דרך הטופס הידני בכרטיס העסקה.<br>` +
    `מוצר: <b>${productName}</b> · סה"כ: <b>${money(ev.totalEntered)}</b><br>${lines}<br>` +
    `ריצת n8n: ${execLink}</div>`;

  if (saleId) {
    add({ ref: 'noteSale', kind: 'create', object: 'note', label: 'הערה על תהליך המכירה',
      body: { notetext: noteHtml, objectid: saleId, objecttypecode: 4 } });
  } else {
    warnings.push('אין תהליך מכירה — ההערה לא צורפה אליו.');
  }
  ev.payments.forEach((p) => {
    add({ ref: 'note' + p.index, kind: 'create', object: 'note',
      label: `הערה על רשומת התשלום ${p.index}`,
      body: { notetext: noteHtml, objectid: '@pay' + p.index, objecttypecode: 1039 } });
  });

  decisions.push(`נוצרו ${ev.payments.length} רשומות תשלום ו-${ev.payments.reduce((a, p) => a + p.count, 0)} תיעודי תשלום.`);

  // ========================================================================
  // 🔴 16/09/2026 — מעבר תוכנית מזוהה מהנתונים, לא מתיבת סימון
  // ------------------------------------------------------------------------
  // הכשל שנתפס חי (יהודית סואייה): נסלק תשלום של 4,455 ₪ על "תוכנית ליווי
  // 17 שבועות" בזמן שרשומת הליווי שלה הייתה על "בוסט". מכיוון ש"רכישה של
  // מוצר חדש" לא סומן בטופס, התהליך המקצועי לא רץ, והליווי נשאר בוסט.
  // תיבת סימון שהמשתמש שוכח לסמן היא נקודת כשל — לכן ההחלטה נגזרת עכשיו
  // מהמציאות: אם המוצר שנסלק שייך לקטגוריה אחרת מזו שהלקוחה נמצאת בה,
  // זו רכישת מוצר חדש בפועל, גם בלי סימון.
  // ========================================================================
  const CAT_OF_PROGRAM = { 1: '100', 2: '101', 4: '102' };
  const PROGRAM_LABEL = { 1: 'בוסט', 2: 'פרימיום', 3: 'מתקדמים', 4: 'המשך' };
  const catOf = (pid) => {
    const pr = products.find((x) => U(x.productid) === U(pid));
    return pr ? S(pr.categorycode) : '';
  };
  const paidCat = product ? S(product.categorycode) : catOf(ev.productId);
  const mentoring = mentorings.find((m) => U(m.pcfaccountid) === U(ev.accountid)) || mentorings[0] || null;
  const curProgram = mentoring ? Number(mentoring.pcfCurrentProgram) || 0 : 0;
  const curCat = CAT_OF_PROGRAM[curProgram] || '';

  // 🔴 ההפעלה האוטומטית מוגבלת ל**מעבר תוכנית מוכח**: קיימת רשומת ליווי,
  //    והקטגוריה שלה שונה מזו שנסלקה. כשאין רשומת ליווי כלל לא יורים
  //    אוטומטית — הטופס משמש גם לתשלומים נוספים על עסקה קיימת, וירי עיוור
  //    היה שולח הודעות ללקוחה על לא כלום. במקרה כזה נפתחת משימה.
  let programChange = false;
  let noMentoring = false;
  if (paidCat && ev.accountid) {
    if (!mentoring) noMentoring = true;
    else if (curCat && curCat !== paidCat) programChange = true;
  }

  const firePro = !!ev.newProductPurchase || programChange;
  if (ev.newProductPurchase) {
    decisions.push('סומן "רכישה של מוצר חדש" — התהליך המקצועי יופעל.');
  } else if (programChange) {
    warnings.push(`⚠️ לא סומן "רכישה של מוצר חדש" בטופס, אבל המוצר שנסלק ("${productName}") שייך לקטגוריה אחרת מזו שהלקוחה נמצאת בה${mentoring ? ` (${PROGRAM_LABEL[curProgram] || 'לא ידוע'})` : ' (אין לה רשומת ליווי כלל)'}. התהליך המקצועי הופעל בכל זאת — אחרת הליווי היה נשאר על התוכנית הישנה.`);
    decisions.push('התהליך המקצועי הופעל לפי מעבר התוכנית שזוהה בנתונים, לא לפי תיבת הסימון.');
  } else if (noMentoring) {
    warnings.push(`⚠️ אין ללקוחה רשומת ליווי כלל, ולא סומן "רכישה של מוצר חדש". התהליך המקצועי **לא** הופעל אוטומטית כדי לא לשלוח הודעות בטעות על תשלום משלים — נפתחה משימה לבדיקה ידנית.`);
    add({ ref: 'taskNoMentoring', kind: 'create', object: '10', label: 'משימת בדיקה — אין רשומת ליווי',
      body: {
        subject: cut(`אין תהליך ליווי ללקוחה שנסלקה · ${custLabel}`, 190),
        description:
          `<div dir="rtl">נקלט תשלום של <b>${money(ev.totalEntered)}</b> על <b>${productName}</b>, ` +
          `אבל ללקוחה <b>אין רשומת תהליך ליווי</b> במערכת.<br><br>` +
          `<b>מה לעשות:</b> לבדוק אם זו רכישה חדשה שדורשת פתיחת ליווי. אם כן — להריץ את התשלום ` +
          `מחדש דרך הטופס עם <b>"רכישה של מוצר חדש" = כן</b>, או לפתוח את הליווי ידנית.<br>` +
          `<b>הסיבה שלא בוצע אוטומטית:</b> הטופס משמש גם לתשלומים משלימים על עסקה קיימת. ` +
          `הפעלה אוטומטית הייתה שולחת ללקוחה הודעת ברוכה הבאה וצירוף לקבוצה על תשלום שאינו רכישה.<br><br>` +
