  } else {
    decisions.push('לא סומנה רכישת מוצר חדש והמוצר באותה קטגוריה של הליווי — התהליך המקצועי לא יופעל.');
  }

  // ========================================================================
  // 🔴 זיהוי כפילות תהליך מכירה — כלל אליאל: תהליך מכירה אחד לכל קטגוריה.
  // אי אפשר להזיז את התשלום לבד (המשתמש עמד על העסקה הזו במודע), ולכן
  // נפתחת משימה מפורשת עם שני המזהים, כדי שהאיחוד ייעשה בידיים.
  // ========================================================================
  if (paidCat && saleId && allSales.length) {
    const sameCat = allSales.filter((x) =>
      U(x.opportunityid) !== U(saleId) && catOf(x.pcfProduct) === paidCat);
    const noProductOpen = allSales.filter((x) =>
      U(x.opportunityid) !== U(saleId) && !S(x.pcfProduct) && Number(x.statuscode) !== 11 && Number(x.statuscode) !== 12);
    if (sameCat.length) {
      const names = sameCat.map((x) => `"${S(x.name)}"`).join(', ');
      warnings.push(`⚠️ ללקוחה כבר קיים תהליך מכירה בקטגוריה של "${productName}" (${names}). לפי הכלל "תהליך מכירה אחד לכל קטגוריה" נוצרה כאן כפילות.`);
      add({ ref: 'taskDupSale', kind: 'create', object: '10', label: 'משימת איחוד תהליכי מכירה כפולים',
        body: {
          subject: cut(`איחוד תהליכי מכירה כפולים · ${custLabel}`, 190),
          description:
            `<div dir="rtl">נקלט תשלום על <b>${productName}</b> לתהליך המכירה <b>${S(sale && sale.name) || saleId}</b>, ` +
            `אבל ללקוחה כבר קיים תהליך מכירה באותה קטגוריה: ${names}.<br><br>` +
            `<b>מה לעשות:</b> לאחד את שני התהליכים — להעביר את התשלומים, תיעודי התשלום והליווי לתהליך אחד, ולמחוק את השני.<br>` +
            `<b>הסיבה:</b> תהליך מכירה מייצג קטגוריה (בוסט / פרימיום / המשך) ולא רכישה בודדת. ` +
            `פתיחת תהליך חדש ידנית כשכבר קיים אחד מאותה קטגוריה מייצרת כפילות.<br>` +
            `<b>למניעה בפעם הבאה:</b> לפני פתיחת תהליך מכירה חדש — לבדוק בתיק הלקוחה אם כבר יש תהליך מאותה קטגוריה, ולסלוק עליו.<br><br>` +
            `ריצה: ${execLink}</div>`,
          accountid: ev.accountid, pcfSale: saleId,
          ownerid: ownerid || '',
          prioritycode: cfg.DEFAULT_TASK_PRIORITY, pcfTaskType: cfg.DEFAULT_TASK_TYPE,
          statuscode: cfg.DEFAULT_TASK_STATUS,
        } });
    } else if (noProductOpen.length) {
      const names = noProductOpen.map((x) => `"${S(x.name)}"`).join(', ');
      warnings.push(`ללקוחה יש תהליך מכירה פתוח בלי מוצר (${names}) — היה אפשר לסלוק עליו במקום לפתוח חדש.`);
    }
  }

  return {
    branch: 'MANUAL_PAYMENT', ops, warnings, decisions,
    summary: `נקלטו ${ev.payments.length} אמצעי תשלום בסך ${money(ev.totalEntered)}.`,
    saleId, productName, ownerid,
    programChange, currentProgram: curProgram, paidCategory: paidCat,
    firePro,
  };
}

