// ============================================================================
// WF-27 · גל 1 — יצירת רשומות התשלום (1039)
// ============================================================================
// בטופס הידני יכולים להיות כמה אמצעי תשלום, ולכן יש **כמה רשומות אב** ולא אחת.
// כל שאר הפעולות (תיעודי תשלום, הערות) מפנות אליהן ורצות בגל 2.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const plan = ctx.plan;
  const base = plan._cfg.FIREBERRY_BASE;
  const ops = Array.isArray(plan.ops) ? plan.ops : [];

  const NOOP = {
    _noop: true, ref: '_noop', label: 'אין פעולות בגל זה',
    method: 'POST', url: `${base}/api/v3/query`,
    body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
  };

  // 🔒 מנעול בטיחות שני — תוכנית שאינה מסומנת לכתיבה לא מייצרת קריאת כתיבה.
  if (plan.DRY_RUN !== false) {
    return [{ json: Object.assign({}, NOOP, { _blocked: true, _rest: [],
      label: '🔒 נחסם — התוכנית אינה מסומנת לכתיבה בפועל' }) }];
  }

  const parents = ops.filter((o) => o.object === '1039' && o.kind === 'create');
  const rest = ops.filter((o) => parents.indexOf(o) === -1);

  if (!parents.length) return [{ json: Object.assign({}, NOOP, { _rest: rest }) }];

  return parents.map((op) => ({ json: {
    _noop: false, ref: op.ref, label: op.label, object: op.object, kind: op.kind,
    method: 'POST', url: `${base}/api/record/${op.object}`, body: op.body,
    _rest: rest,
  } }));
}

// ==== N8N BINDING ====
return LOGIC({ plan: $('בניית תוכנית תשלום').first().json });

// ============================================================================
// WF-27 · גל 2 — תיעודי תשלום והערות, עם פתרון ההפניות לרשומות שנוצרו
// ============================================================================
// ההצמדה בין בקשה לתשובה נעשית לפי סדר הפריטים — צומת ה-HTTP של n8n מחזיר
// פריט אחד לכל פריט נכנס, באותו סדר.
// ============================================================================

// ==== LOGIC (pure) ====
function extractRecordId(resp, object) {
  if (!resp || typeof resp !== 'object') return '';
  const idKey = `customobject${object}id`;
  const cands = [
    resp[idKey], resp.id, resp._id, resp.noteid,
    resp.data && resp.data[idKey], resp.data && resp.data.id, resp.data && resp.data._id,
    resp.Record && resp.Record[idKey],
    resp.data && resp.data.Record && resp.data.Record[idKey],
    resp.data && resp.data.Data && resp.data.Data[0] && resp.data.Data[0][idKey],
  ];
  for (const c of cands) {
    const v = (c === undefined || c === null) ? '' : String(c).trim();
    if (v && /^[0-9a-fA-F-]{30,}$/.test(v)) return v;
  }
  return '';
}

function resolveRefs(value, refs) {
  if (typeof value === 'string' && value.charAt(0) === '@') {
    const key = value.slice(1);
    return refs[key] !== undefined ? refs[key] : '';
  }
  if (Array.isArray(value)) return value.map((v) => resolveRefs(v, refs));
  if (value && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value)) {
      const rv = resolveRefs(value[k], refs);
      // הפניה ריקה בשדה מזהה מחזירה 403 בפיירברי — לא כותבים אותה כלל
      if (rv === '' && typeof value[k] === 'string' && value[k].charAt(0) === '@') continue;
      out[k] = rv;
    }
    return out;
  }
  return value;
}

function LOGIC(ctx) {
  const plan = ctx.plan;
  const base = plan._cfg.FIREBERRY_BASE;
  const reqs = ctx.w1Reqs || [];
  const resps = ctx.w1Resps || [];

  const NOOP = {
    _noop: true, ref: '_noop', label: 'אין פעולות בגל 2',
    method: 'POST', url: `${base}/api/v3/query`,
    body: { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 },
  };
  if (plan.DRY_RUN !== false) return [{ json: Object.assign({}, NOOP, { _blocked: true }) }];

  // 🔴 פיירברי עלול להחזיר 400 ולכתוב את הרשומה בכל זאת — לכן מזהה שלא חולץ
  //    נבדק מול שאילתת האימות לפי המזהה החיצוני שכתבנו ברשומה.
  const verify = (ctx.verifyResp && Array.isArray(ctx.verifyResp.data)) ? ctx.verifyResp.data : [];
  const refs = {};
  const recovered = [];
  reqs.forEach((r, i) => {
    if (!r || r._noop || !r.ref) return;
    let id = extractRecordId(resps[i], r.object);
    if (!id) {
      const key = String((r.body && r.body.pcfExternalSoftwareID1) || '');
      const hit = verify.find((x) => x && String(x.pcfExternalSoftwareID1 || '') === key);
      if (hit && hit.customobject1039id) { id = String(hit.customobject1039id); recovered.push(r.ref); }
    }
    refs[r.ref] = id;
  });

  const rest = (reqs[0] && reqs[0]._rest) || [];
  if (!rest.length) return [{ json: Object.assign({}, NOOP, { _refs: refs, _recovered: recovered }) }];

  return rest.map((op) => {
    const body = resolveRefs(op.body, refs);
    // תיעוד תשלום בלי רשומת אב, או הערה בלי יעד — לא נוצרים יתומים
    const orphan = (op.object === '1018' && !body.pcfPaymentCollection)
                || (op.object === 'note' && !body.objectid);
    return { json: {
      _noop: !!orphan, ref: op.ref,
      label: op.label + (orphan ? ' (דולג — לא נמצא מזהה אב)' : ''),
      object: op.object, kind: op.kind,
      method: orphan ? 'POST' : 'POST',
      url: orphan ? NOOP.url : `${base}/api/record/${op.object}`,
      body: orphan ? NOOP.body : body,
      _refs: refs, _recovered: recovered,
    } };
  });
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית תשלום').first().json,
  w1Reqs: $('גל 1 · רשומות התשלום').all().map((i) => i.json),
