});

// ============================================================================
// WF-27 · סיכום הריצה + הפעלת התהליך המקצועי
// ============================================================================
// התהליך המקצועי (WF-22) מופעל **אך ורק** כשסומן "רכישה של מוצר חדש",
// וכשקליטת התשלום עצמה הצליחה.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const plan = ctx.plan;
  const cfg = plan._cfg;
  const looksLikeError = (r) => {
    if (!r || typeof r !== 'object') return true;
    if (r.success === false) return true;
    if (r.Message || r.message) return true;
    if (r.error) return true;
    return false;
  };

  const results = [];
  const pair = (reqs, resps, wave) => {
    (reqs || []).forEach((req, i) => {
      if (!req || req._noop || req._blocked) return;
      results.push({ wave, ref: req.ref, label: req.label, object: req.object,
        ok: !looksLikeError((resps || [])[i]), response: (resps || [])[i] });
    });
  };
  pair(ctx.w1Reqs, ctx.w1Resps, 1);
  pair(ctx.w2Reqs, ctx.w2Resps, 2);

  const failed = results.filter((r) => !r.ok);
  const recovered = (ctx.w2Reqs && ctx.w2Reqs[0] && ctx.w2Reqs[0]._recovered) || [];
  const success = failed.length === 0;

  const IDLE = `${cfg.FIREBERRY_BASE}/api/v3/query`;
  const idleBody = { objectType: 1039, fields: [{ name: 'customobject1039id' }], pageSize: 1, pageNumber: 1 };

  let pro = { fired: false, reason: '' };
  let proUrl = IDLE, proBody = idleBody;
  if (plan.DRY_RUN === true) pro.reason = 'DRY_RUN — התהליך המקצועי לא הופעל';
  else if (!plan.firePro) pro.reason = 'לא סומנה רכישת מוצר חדש והמוצר באותה קטגוריה של הליווי';
  else if (!success) pro.reason = 'קליטת התשלום לא הושלמה — התהליך המקצועי לא הופעל';
  else if (!plan.accountid) pro.reason = 'אין לקוחה משויכת';
  else {
    pro = { fired: true, reason: '' };
    proUrl = cfg.PRO_WEBHOOK_URL;
    proBody = {
      accountid: plan.accountid,
      accountName: plan.accountName,
      phone: plan.phone,
      saleid: plan.saleId,
      productId: plan.productId,
      productName: plan.productName,
      grossTotal: plan.totalEntered,
      asmachta: plan.idemBase,
      purchaseDate: plan.todayISO,
      paymentBranch: 'MANUAL_PAYMENT',
      executionUrl: plan.executionUrl,
    };
  }

  return [{ json: {
    success, dryRun: plan.DRY_RUN,
    branch: plan.branch, summary: plan.summary,
    decisions: plan.decisions, warnings: plan.warnings,
    account: { id: plan.accountid, name: plan.accountName },
    saleid: plan.saleId, product: plan.productName,
    paymentsCount: plan.paymentsCount,
    totalEntered: plan.totalEntered,
    operations: results,
    failedCount: failed.length,
    recoveredParents: recovered,
    professionalProcess: pro,
    proUrl, proBody,
    executionUrl: plan.executionUrl,
  } }];
}

// ==== N8N BINDING ====
return LOGIC({
  plan: $('בניית תוכנית תשלום').first().json,
  w1Reqs: $('גל 1 · רשומות התשלום').all().map((i) => i.json),
  w1Resps: $('יצירת רשומות התשלום').all().map((i) => i.json),
  w2Reqs: $('גל 2 · תיעודים והערות').all().map((i) => i.json),
